#!/usr/bin/env python3
"""Exercise the native binary against the real C firmware simulator."""
import json
from pathlib import Path
import subprocess
import unittest

BIN='build/player/letki-player'
class PlayerCLI(unittest.TestCase):
    def run_player(self,*args,ok=True):
        p=subprocess.run([BIN,*args],capture_output=True,text=True,timeout=30)
        self.assertEqual(p.returncode,0 if ok else 1,p.stdout+p.stderr)
        return p
    def test_full_bell_show(self):
        # The existing generated score is optional in a clean checkout. The
        # synthetic WAV is generated by the native test, without external assets.
        p=self.run_player('--show','config/player/bell-demo.json','--audio','build/player/test-tone.wav','--check','--report','build/player/cli-check.json')
        report=json.loads(Path('build/player/cli-check.json').read_text())
        self.assertEqual(report['status'],'checked');self.assertGreater(report['frames'],10)
        self.assertFalse(report['hardware'])
        self.assertNotIn('Connecting to',p.stdout)
    def test_both_named_presets_with_introductions(self):
        for name in ('tubular-bells','adagio','ore-ore','tubular-theatre'):
            self.run_player('--show',f'config/player/{name}.json','--audio','build/player/test-tone.wav','--check')
    def test_full_precision_pwm(self):
        self.run_player('--show','config/player/bell-demo.json','--audio','build/player/test-tone.wav','--format','level8','--check')
        self.run_player('--format','invalid',ok=False)
    def test_video_through_firmware(self):
        self.run_player('--show','config/player/bell-demo.json','--audio','build/player/test-tone.wav','--video','build/player/test-video.mkv','--check','--report','build/player/video-cli.json')
        report=json.loads(Path('build/player/video-cli.json').read_text())
        self.assertEqual(report['fft_bands'],24)
        self.assertTrue(report['video'])
        self.assertFalse(report['video_on_leds'])
        self.assertEqual(report['video_target'],'PC preview only')
        self.run_player('--video-mode','invalid',ok=False)
    def test_missing_audio_is_clear(self):
        Path('build/player/no-audio.json').write_text(json.dumps({'name':'missing audio'}))
        p=self.run_player('--show','build/player/no-audio.json',ok=False)
        self.assertIn('Provide --audio',p.stderr)
    def test_check_rejects_hardware(self):
        p=self.run_player('--check','--port','/does/not/exist',ok=False)
        self.assertIn('cannot access hardware',p.stderr)
    def test_seek_range_and_options(self):
        self.run_player('--help')
        self.run_player('--fps','0',ok=False)
        self.run_player('--baud','460800',ok=False)
        self.run_player('--seconds','nan',ok=False)
        self.run_player('--show','config/player/bell-demo.json','--audio','build/player/test-tone.wav','--seek','20','--check',ok=False)
    def test_offline_frame_export(self):
        out=Path('build/player/cli-frames.bin')
        self.run_player('--show','config/player/bell-demo.json','--audio','build/player/test-tone.wav','--check','--frames',str(out))
        header,pixels=out.read_bytes().split(b'\n',1)
        self.assertEqual(header,b'LETKI-FRAMES 1 40 8 12 0')
        self.assertEqual(len(pixels)%320,0)
        self.assertGreater(len(pixels),320)
        self.assertLessEqual(max(pixels),100)
        self.run_player('--frames',str(out),ok=False)
    def test_simulation_and_offline_connection_guards(self):
        p=self.run_player('--simulate','--inspect')
        self.assertNotIn('Connecting to',p.stdout)
        self.run_player('--simulate','--port','/does/not/exist',ok=False)
        self.run_player('--analyze','--port','/does/not/exist',ok=False)
        p=self.run_player('--show','config/player/bell-demo.json','--audio','build/player/test-tone.wav','--analyze','--report','build/player/cli-offline-analysis.json')
        self.assertNotIn('Connecting to',p.stdout)
    def test_silent_real_time(self):
        self.run_player('--show','config/player/bell-demo.json','--audio','build/player/test-tone.wav','--simulate','--silent','--headless','--seconds','.2','--report','build/player/cli-silent.json')

if __name__=='__main__':unittest.main()
